hold.example:
// client: keep the page up while the character loads
const { LoadingScreen } = kcds.ui;

LoadingScreen.hold();
kcds.core.Events.on('playerReady', () => {
  setTimeout(() => LoadingScreen.release(), 3000);
});

hold.exampleCs:
// client: keep the page up while the character loads

LoadingScreen.Hold();
Events.On("playerReady", () =>
{
    Timers.SetTimeout(() => LoadingScreen.Release(), 3000);
});

release.example:
if (kcds.ui.LoadingScreen.release()) {
  console.log('the player sees the world');
}

release.exampleCs:
if (LoadingScreen.Release())
{
    Log.Info("the player sees the world");
}
